package net.officefloor.hq.app.quick;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a draft claim, dated the sheet's entry date (its today when none is set) with an empty note, for the person with this name (ignoring
 *  case), adding them first with grade A when the sheet has no one by that name (refused when the name is already
 *  a name or alias on another sheet of the sheet's tree). One change: every check
 *  runs before anything is written, so a refusal leaves no new person and no audit record behind. */
public class QuickAdd {
    public void add(@PathVariable("sheetId") String sheetId, @Val QuickAddInput input,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            PeriodRepository periods, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!people.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        LocalDate date = sheets.entryDate(id);
        Person person = people.findByName(id, input.name());
        PeriodGuard.open(periods, id, person != null ? claims.dueBy(id, person.id(), date) : claims.dueByOfGrade(id, "A", date));
        if (person != null) {
            people.claimAllowed(id, person.id(), date);
        } else if (people.nameTaken(id, input.name(), 0)) {
            throw new BadRequestException("name is already in use");
        }
        if (person == null) {
            Rollup.Snapshot before = rollup.take(id);
            try {
                person = people.add(id, input.name(), "A", null);
            } catch (DuplicateKeyException e) {
                throw new BadRequestException("name is already in use");
            }
            audit.record("PERSON_ADDED sheet=" + id + " by=" + by + " name=" + person.name()
                    + " grade=" + person.grade());
            rollup.record(id, by, before);
        }
        Rollup.Snapshot before = rollup.take(id);
        Claim added = claims.add(id, person.id(), input.amount(), date, "", null);
        claims.log(id, added.id(), by);
        audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + person.name()
                + " amount=" + added.amount() + " date=" + added.date());
        if (added.lateEntry()) {
            audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + person.name()
                    + " amount=" + added.amount() + " date=" + added.date());
        }
        rollup.record(id, by, before);
        claim.set(added);
    }
}
package net.officefloor.hq.app.importing;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.person.NewPerson;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the people import box: each non-blank line is name,grade,terms,contact (the last two may be absent
 *  or blank), bound by the person form's rules. A name or contact given twice in the import (ignoring case)
 *  is refused, as is an import with no lines. */
public class ValidateImport {
    public void validate(@RequestBody ImportRequest request, Out<ImportInput> input) throws BadRequestException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PersonRequest> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\r?\n", -1)) {
            n++;
            if (raw.isBlank()) {
                continue;
            }
            String[] f = raw.split(",", -1);
            try {
                if (f.length > 4) {
                    throw new BadRequestException("give name,grade,terms,contact");
                }
                PersonRequest person = NewPerson.check(new PersonRequest(f[0], f.length > 1 ? f[1] : "", null, "",
                        f.length > 2 ? f[2] : "", f.length > 3 ? f[3] : "", null, ""));
                if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                    throw new BadRequestException("name " + person.name() + " is given twice in the import");
                }
                if (!person.contact().isEmpty() && !contacts.add(person.contact())) {
                    throw new BadRequestException("contact " + person.contact() + " is given twice in the import");
                }
                people.add(person);
            } catch (BadRequestException e) {
                throw new BadRequestException("line " + n + ": " + e.getMessage());
            }
        }
        if (people.isEmpty()) {
            throw new BadRequestException("import at least one line");
        }
        input.set(new ImportInput(people));
    }
}
